from src.nodes.base import BaseNode
from src.runtime.assets.realization import get_asset_converter
import json

class Hou_Mcp_Asset_Convert(BaseNode):
    name = "hou_mcp_asset_convert"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("asset_json",    "string", widget_type="text")
        self.add_input("target_format", "string", widget_type="text", default="usd")
        self.add_output("conversion_result_json", "string")
        self.add_output("source_format",          "string")
        self.add_output("target_format_out",      "string")
        self.add_output("conversion_ok",          "bool")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        asset_json    = inputs.get("asset_json", "") or ""
        target_format = str(inputs.get("target_format") or "usd")

        if not asset_json.strip():
            self.log_error("No asset_json provided.")
            return {"conversion_result_json": "{}", "source_format": "", "target_format_out": target_format, "conversion_ok": False, "exec_out": True}

        try:
            asset = json.loads(asset_json)
        except Exception as exc:
            self.log_error(f"Failed to parse asset_json: {exc}")
            return {"conversion_result_json": "{}", "source_format": "", "target_format_out": target_format, "conversion_ok": False, "exec_out": True}

        try:
            result = get_asset_converter().convert(asset, target_format)
            self.log_info(f"Converted '{result.asset_name}' {result.source_format}->{result.target_format} ok={result.ok}")
            return {
                "conversion_result_json": json.dumps(result.to_dict(), sort_keys=True, default=str),
                "source_format":          result.source_format,
                "target_format_out":      result.target_format,
                "conversion_ok":          result.ok,
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Asset conversion failed: {exc}")
            return {"conversion_result_json": "{}", "source_format": "", "target_format_out": target_format, "conversion_ok": False, "exec_out": True}

def register_node():
    return Hou_Mcp_Asset_Convert
